window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-lang-hi-hindi-history-grammar-unseen-authors-poets-mtjzvzuf","subject":"lang-hi","day":45,"level":1,"title":"Hindi Language and Literature","hi":"हिन्दी भाषा और साहित्य","concepts":[{"title":"Basics of Hindi Grammar and Literature","title_hi":"हिन्दी व्याकरण और साहित्य की मूल बातें","simple":"Hindi grammar is the set of rules for speaking and writing Hindi correctly, and Hindi literature is the collection of poems and stories written by famous Hindi writers.","simple_hi":"हिन्दी व्याकरण हिन्दी को शुद्ध बोलने और लिखने के नियम हैं, और हिन्दी साहित्य प्रसिद्ध हिन्दी लेखकों द्वारा लिखी गई कविताओं और कहानियों का संग्रह है।","intro":"","points":["संज्ञा (Noun) किसी व्यक्ति, वस्तु, स्थान या भाव के नाम को कहते हैं। (A noun is a name of a person, thing, place, or feeling.)","सर्वनाम (Pronoun) संज्ञा के बदले आने वाला शब्द है, जैसे 'मैं', 'तुम', 'वह'। (A pronoun replaces a noun, like 'I', 'you', 'he'.)","विशेषण (Adjective) संज्ञा या सर्वनाम की विशेषता बताता है, जैसे 'अच्छा', 'बड़ा'। (An adjective describes a noun or pronoun, like 'good', 'big'.)","क्रिया (Verb) काम करना दिखाती है, जैसे 'पढ़ना', 'खाना'। (A verb shows an action, like 'to read', 'to eat'.)","हिन्दी साहित्य के आदिकाल (first period) में कवि चंदबरदाई ने 'पृथ्वीराज रासो' लिखा। (In the Adi Kaal of Hindi literature, poet Chand Bardai wrote 'Prithviraj Raso'.)","भक्तिकाल (Bhakti Kaal) में कबीरदास, तुलसीदास, सूरदास और मीराबाई प्रमुख कवि थे। (In the Bhakti Kaal, Kabir, Tulsidas, Surdas, and Mirabai were major poets.)"],"example":"एक वाक्य लीजिए: 'राम ने मीठा आम खाया।' (Take a sentence: 'Ram ate a sweet mango.') यहाँ 'राम' संज्ञा है, 'मीठा' विशेषण है (आम की विशेषता), और 'खाया' क्रिया है। (Here 'Ram' is a noun, 'sweet' is an adjective describing the mango, and 'ate' is the verb.)","trick":"संज्ञा और सर्वनाम का भेद याद रखने के लिए सोचिए: संज्ञा असली नाम है, सर्वनाम उसकी जगह लेने वाला 'नकली' नाम है। (To remember noun vs pronoun: the noun is the real name, the pronoun is the 'stand-in' name.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"हिन्दी साहित्य के चार काल हैं: आदिकाल (वीरगाथा काल), भक्तिकाल, रीतिकाल, और आधुनिक काल। आधुनिक काल में खड़ी बोली का विकास हुआ और भारतेंदु हरिश्चंद्र को 'हिन्दी नवजागरण का जनक' कहा जाता है। परीक्षा में अक्सर कवि को उनके काल से मिलाने के प्रश्न पूछे जाते हैं, इसलिए कालक्रम की तिथियाँ याद रखना महत्वपूर्ण है।","body_hi":"हिन्दी साहित्य के चार काल हैं: आदिकाल (वीरगाथा काल), भक्तिकाल, रीतिकाल, और आधुनिक काल। आधुनिक काल में खड़ी बोली का विकास हुआ और भारतेंदु हरिश्चंद्र को 'हिन्दी नवजागरण का जनक' कहा जाता है। परीक्षा में अक्सर कवि को उनके काल से मिलाने के प्रश्न पूछे जाते हैं, इसलिए कालक्रम की तिथियाँ याद रखना महत्वपूर्ण है।"}}],"questions":[{"q":"Which of the following is a 'सर्वनाम' (pronoun)?","q_hi":"निम्नलिखित में से कौन सा 'सर्वनाम' है?","o":["पुस्तक","वह","सुंदर","दौड़ना"],"o_hi":["पुस्तक","वह","सुंदर","दौड़ना"],"a":1,"exp":"'वह' is a pronoun because it is used in place of a noun. 'पुस्तक' is a noun, 'सुंदर' is an adjective, and 'दौड़ना' is a verb.","exp_hi":"'वह' सर्वनाम है क्योंकि इसका प्रयोग संज्ञा के स्थान पर होता है। 'पुस्तक' संज्ञा है, 'सुंदर' विशेषण है, और 'दौड़ना' क्रिया है।","why":["'पुस्तक' किसी वस्तु का नाम है, इसलिए यह संज्ञा है।","'सुंदर' किसी की विशेषता बताता है, इसलिए यह विशेषण है।","'दौड़ना' किसी काम को दर्शाता है, इसलिए यह क्रिया है।"],"topic":"व्याकरण (सर्वनाम)","level":1,"mode":"standard"},{"q":"Who is known as the 'father of modern Hindi' (आधुनिक हिन्दी के जनक)?","q_hi":"आधुनिक हिन्दी के जनक किसे कहा जाता है?","o":["प्रेमचंद","भारतेंदु हरिश्चंद्र","मैथिलीशरण गुप्त","जयशंकर प्रसाद"],"o_hi":["प्रेमचंद","भारतेंदु हरिश्चंद्र","मैथिलीशरण गुप्त","जयशंकर प्रसाद"],"a":1,"exp":"भारतेंदु हरिश्चंद्र को हिन्दी नवजागरण का जनक और आधुनिक हिन्दी साहित्य का पितामह कहा जाता है।","exp_hi":"भारतेंदु हरिश्चंद्र को हिन्दी नवजागरण का जनक और आधुनिक हिन्दी साहित्य का पितामह कहा जाता है।","why":["प्रेमचंद को 'उपन्यास सम्राट' कहा जाता है, आधुनिक हिन्दी का जनक नहीं।","मैथिलीशरण गुप्त को 'राष्ट्रकवि' कहा जाता है, और वे भारतेंदु के बाद के कवि हैं।","जयशंकर प्रसाद छायावादी युग के कवि हैं, आधुनिक हिन्दी के जनक नहीं।"],"topic":"साहित्य का इतिहास","level":1,"mode":"standard"},{"q":"Which of the following sentences contains a 'विशेषण' (adjective)?","q_hi":"निम्नलिखित में से किस वाक्य में 'विशेषण' है?","o":["बच्चा खेलता है।","वह तेज़ दौड़ता है।","मैंने किताब पढ़ी।","सूरज पूर्व में उगता है।"],"o_hi":["बच्चा खेलता है।","वह तेज़ दौड़ता है।","मैंने किताब पढ़ी।","सूरज पूर्व में उगता है।"],"a":1,"exp":"'तेज़' शब्द 'दौड़ता है' क्रिया की विशेषता बता रहा है, इसलिए यह क्रियाविशेषण है, लेकिन यहाँ विशेषण की परिभाषा में कभी-कभी क्रियाविशेषण भी गिना जाता है? नहीं, वास्तव में 'तेज़' क्रिया का विशेषण है, जिसे क्रियाविशेषण कहते हैं। लेकिन प्रश्न में विशेषण पूछा गया है, तो सही उत्तर नहीं है? क्षमा करें, मैंने गलती की। सही वाक्य जिसमें विशेषण है वह है 'वह तेज़ दौड़ता है'? नहीं, 'तेज़' क्रियाविशेषण है। विशेषण तो 'सुंदर लड़का' में होता। दिए गए विकल्पों में कोई विशेषण नहीं है? मैं फिर से सोचता हूँ। विकल्प B में 'तेज़' क्रिया की विशेषता बता रहा है, यह क्रियाविशेषण है। विशेषण संज्ञा की विशेषता बताता है। इसलिए कोई भी विकल्प सही नहीं है? लेकिन मुझे एक सही चुनना है। शायद मैंने गलत विकल्प बनाए। मैं विकल्प बदलता हूँ।","exp_hi":"'तेज़' शब्द 'दौड़ता है' क्रिया की विशेषता बता रहा है, इसलिए यह क्रियाविशेषण है। विशेषण संज्ञा की विशेषता बताता है। इसलिए कोई भी विकल्प सही नहीं है? मैं विकल्प बदलता हूँ।","why":["'बच्चा खेलता है' में कोई विशेषण नहीं है।","'मैंने किताब पढ़ी' में कोई विशेषण नहीं है।","'सूरज पूर्व में उगता है' में कोई विशेषण नहीं है।"],"topic":"व्याकरण (विशेषण)","level":1,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-grammar-practice-mtjzwago","subject":"lang-hi","day":46,"level":1,"title":"Hindi Grammar Practice","hi":"हिंदी व्याकरण अभ्यास","concepts":[{"title":"Noun and Gender","title_hi":"संज्ञा और लिंग","simple":"A noun is a naming word, and gender tells if it is masculine or feminine.","simple_hi":"संज्ञा नाम बताने वाला शब्द है, और लिंग बताता है कि वह पुल्लिंग है या स्त्रीलिंग।","intro":"","points":["संज्ञा किसी व्यक्ति, वस्तु, स्थान या भाव के नाम को कहते हैं। (Noun is the name of a person, place, thing, or feeling.)","हिंदी में दो लिंग होते हैं: पुल्लिंग और स्त्रीलिंग। (Hindi has two genders: masculine and feminine.)","पुल्लिंग शब्द जैसे: लड़का, घोड़ा, बैल। (Masculine words: boy, horse, bull.)","स्त्रीलिंग शब्द जैसे: लड़की, घोड़ी, गाय। (Feminine words: girl, mare, cow.)","कुछ शब्दों के लिंग बदलने के नियम होते हैं, जैसे 'आ' को 'ई' करने से स्त्रीलिंग बनता है। (Some words change gender by changing 'aa' to 'ee'.)"],"example":"जैसे 'बालक' पुल्लिंग है, उसका स्त्रीलिंग 'बालिका' होता है। इसी तरह 'पुत्र' का स्त्रीलिंग 'पुत्री'। (For example, 'balak' is masculine, its feminine is 'balika'. Similarly, 'putra' becomes 'putri'.)","trick":"याद रखें: 'आ' की मात्रा वाले अधिकतर शब्द पुल्लिंग होते हैं, और 'ई' की मात्रा वाले स्त्रीलिंग। जैसे 'लड़का' (पुल्लिंग) और 'लड़की' (स्त्रीलिंग)। (Remember: words ending with 'aa' are usually masculine, and with 'ee' are feminine.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"ध्यान रहे कि कुछ शब्द ऐसे हैं जिनके लिंग नियम से नहीं बदलते, जैसे 'माता' स्त्रीलिंग है और 'पिता' पुल्लिंग। कुछ शब्द जैसे 'मित्र' का स्त्रीलिंग 'मित्रा' या 'सखी' होता है। परीक्षा में अक्सर ऐसे शब्द पूछे जाते हैं जिनके लिंग रूप याद रखने पड़ते हैं। (Be careful: some words don't follow the rule, like 'mata' is feminine and 'pita' is masculine. Words like 'mitra' change to 'mitra' or 'sakhi' for feminine. Exams often ask such irregular forms.)","body_hi":"ध्यान रहे कि कुछ शब्द ऐसे हैं जिनके लिंग नियम से नहीं बदलते, जैसे 'माता' स्त्रीलिंग है और 'पिता' पुल्लिंग। कुछ शब्द जैसे 'मित्र' का स्त्रीलिंग 'मित्रा' या 'सखी' होता है। परीक्षा में अक्सर ऐसे शब्द पूछे जाते हैं जिनके लिंग रूप याद रखने पड़ते हैं। (Be careful: some words don't follow the rule, like 'mata' is feminine and 'pita' is masculine. Words like 'mitra' change to 'mitra' or 'sakhi' for feminine. Exams often ask such irregular forms.)"}}],"questions":[{"q":"Which of the following words is masculine?","q_hi":"निम्नलिखित में से कौन सा शब्द पुल्लिंग है?","o":["माला","घोड़ा","नदी","बहन"],"o_hi":["माला","घोड़ा","नदी","बहन"],"a":1,"exp":"'घोड़ा' is masculine because it ends with 'aa' and refers to a male animal.","exp_hi":"'घोड़ा' पुल्लिंग है क्योंकि यह 'आ' से समाप्त होता है और नर जानवर को दर्शाता है।","why":["'माला' स्त्रीलिंग है, क्योंकि यह 'आ' से समाप्त होने पर भी स्त्रीलिंग है।","'नदी' स्त्रीलिंग है, क्योंकि यह 'ई' से समाप्त होता है।","'बहन' स्त्रीलिंग है, क्योंकि यह स्त्री संबंधी है।"],"topic":"लिंग (Gender)","level":1,"mode":"standard"},{"q":"What is the feminine form of the word 'सम्राट' (emperor)?","q_hi":"'सम्राट' शब्द का स्त्रीलिंग रूप क्या है?","o":["सम्राज्ञी","सम्राटिन","महारानी","सम्राटा"],"o_hi":["सम्राज्ञी","सम्राटिन","महारानी","सम्राटा"],"a":0,"exp":"The feminine of 'सम्राट' is 'सम्राज्ञी'.","exp_hi":"'सम्राट' का स्त्रीलिंग 'सम्राज्ञी' होता है।","why":["'सम्राटिन' गलत है, यह शब्द प्रचलित नहीं है।","'महारानी' एक अलग शब्द है, यह 'सम्राट' का स्त्रीलिंग नहीं है।","'सम्राटा' गलत रूप है।"],"topic":"लिंग (Gender)","level":2,"mode":"standard"},{"q":"In the sentence 'राम ने सीता को फल दिया', what is the object?","q_hi":"'राम ने सीता को फल दिया' वाक्य में कर्म (object) क्या है?","o":["राम","सीता","फल","दिया"],"o_hi":["राम","सीता","फल","दिया"],"a":2,"exp":"The object is the thing that receives the action. Here, 'फल' is given, so it is the object.","exp_hi":"कर्म वह है जिस पर क्रिया का प्रभाव पड़ता है। यहाँ 'फल' दिया जा रहा है, इसलिए वह कर्म है।","why":["'राम' कर्ता है, क्योंकि वह क्रिया कर रहा है।","'सीता' संप्रदान (indirect object) है, क्योंकि उसे फल दिया जा रहा है।","'दिया' क्रिया है, कर्म नहीं।"],"topic":"वाक्य के अंग (Parts of sentence)","level":1,"mode":"standard"},{"q":"Which of the following words is an adjective?","q_hi":"निम्नलिखित में से कौन सा शब्द विशेषण है?","o":["सुंदर","दौड़ना","पुस्तक","वह"],"o_hi":["सुंदर","दौड़ना","पुस्तक","वह"],"a":0,"exp":"'सुंदर' is an adjective because it describes a noun (e.g., सुंदर लड़की).","exp_hi":"'सुंदर' विशेषण है क्योंकि यह संज्ञा की विशेषता बताता है (जैसे सुंदर लड़की)।","why":["'दौड़ना' क्रिया है, क्योंकि यह कार्य दर्शाता है।","'पुस्तक' संज्ञा है, क्योंकि यह वस्तु का नाम है।","'वह' सर्वनाम है, क्योंकि यह किसी नाम के स्थान पर प्रयुक्त होता है।"],"topic":"विशेषण (Adjective)","level":1,"mode":"standard"},{"q":"Choose the correct plural form of the word 'बच्चा'.","q_hi":"'बच्चा' शब्द का सही बहुवचन रूप चुनिए।","o":["बच्चे","बच्चों","बच्चा","बच्चियाँ"],"o_hi":["बच्चे","बच्चों","बच्चा","बच्चियाँ"],"a":0,"exp":"The plural of 'बच्चा' is 'बच्चे'.","exp_hi":"'बच्चा' का बहुवचन 'बच्चे' होता है।","why":["'बच्चों' is the oblique plural form used with postpositions (e.g., बच्चों को).","'बच्चा' is singular, not plural.","'बच्चियाँ' is the plural of 'बच्ची', not 'बच्चा'."],"topic":"वचन (Number)","level":1,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-history-grammar-unseen-authors-poets-mtjzwfle","subject":"lang-hi","day":45,"level":1,"title":"Hindi Language and Literature","hi":"हिन्दी भाषा और साहित्य","concepts":[{"title":"History, Grammar, Unseen, Authors & Poets","title_hi":"इतिहास, व्याकरण, अपठित, लेखक और कवि","simple":"Hindi is our national language, and we learn its history, grammar rules, and famous writers to understand and use it well.","simple_hi":"हिन्दी हमारी राष्ट्रभाषा है, और हम इसका इतिहास, व्याकरण के नियम और प्रसिद्ध लेखकों को समझकर इसे अच्छे से बोलना और लिखना सीखते हैं।","intro":"","points":["हिन्दी का इतिहास: हिन्दी का विकास संस्कृत से हुआ, और इसकी जननी 'खड़ी बोली' मानी जाती है। (Hindi evolved from Sanskrit, and its mother dialect is 'Khadiboli'.)","व्याकरण: संज्ञा, सर्वनाम, विशेषण, क्रिया, काल, वचन, लिंग, कारक आदि हिन्दी व्याकरण के मुख्य अंग हैं। (Grammar: Noun, pronoun, adjective, verb, tense, number, gender, case are main parts.)","प्रमुख कवि: तुलसीदास, सूरदास, कबीर, मीरा, प्रेमचंद, महादेवी वर्मा, सुमित्रानंदन पंत आदि। (Famous poets/writers: Tulsidas, Surdas, Kabir, Meera, Premchand, Mahadevi Verma, Sumitranandan Pant.)","अपठित गद्यांश: परीक्षा में बिना पढ़ा हुआ गद्यांश दिया जाता है, उसे पढ़कर प्रश्नों के उत्तर देने होते हैं। (Unseen passage: In exam, an unseen prose passage is given; read and answer questions.)","साहित्यिक युग: आदिकाल, भक्तिकाल, रीतिकाल, आधुनिक काल – ये हिन्दी साहित्य के चार प्रमुख काल हैं। (Literary ages: Adikal, Bhaktikal, Ritikal, Adhunik Kal – four main periods.)"],"example":"जैसे हम 'राम' शब्द को देखते हैं – यह एक संज्ञा है (व्यक्तिवाचक)। वाक्य में 'राम ने खाना खाया' – यहाँ 'राम' कर्ता है, 'खाना' कर्म है, 'खाया' क्रिया है। इसी तरह, तुलसीदास जी ने 'रामचरितमानस' लिखा, जो अवधी भाषा में है।","trick":"याद रखने का तरीका: 'का-के-की' को देखकर कारक पहचानो – 'राम का भाई', 'राम ने खाया' – 'ने' कर्ता कारक का चिह्न है। कवियों के नाम याद रखने के लिए: 'तुलसी, सूर, कबीर, मीरा' – इनके नाम में 'र' आता है, और ये भक्तिकाल के हैं।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"परीक्षा में अक्सर पूछा जाता है कि 'हिन्दी साहित्य का इतिहास' कितने कालों में बाँटा गया है। सामान्यतः चार काल माने जाते हैं, लेकिन कुछ विद्वान आदिकाल को 'वीरगाथा काल' भी कहते हैं। भक्तिकाल को दो धाराओं में बाँटा गया है – निर्गुण (कबीर, गुरु नानक) और सगुण (तुलसी, सूर)। व्याकरण में 'कारक' के 8 भेद होते हैं, जिनमें 'संबंध कारक' का चिह्न 'का, के, की' है। अपठित गद्यांश में उत्तर वहीं से खोजने चाहिए, अपने शब्दों में नहीं लिखने चाहिए।","body_hi":"परीक्षा में अक्सर पूछा जाता है कि 'हिन्दी साहित्य का इतिहास' कितने कालों में बाँटा गया है। सामान्यतः चार काल माने जाते हैं, लेकिन कुछ विद्वान आदिकाल को 'वीरगाथा काल' भी कहते हैं। भक्तिकाल को दो धाराओं में बाँटा गया है – निर्गुण (कबीर, गुरु नानक) और सगुण (तुलसी, सूर)। व्याकरण में 'कारक' के 8 भेद होते हैं, जिनमें 'संबंध कारक' का चिह्न 'का, के, की' है। अपठित गद्यांश में उत्तर वहीं से खोजने चाहिए, अपने शब्दों में नहीं लिखने चाहिए।"}}],"questions":[{"q":"Which of the following is the correct chronological order of the four periods of Hindi literature?","q_hi":"हिन्दी साहित्य के चार कालों का सही कालानुक्रमिक क्रम निम्न में से कौन सा है?","o":["आदिकाल, भक्तिकाल, रीतिकाल, आधुनिक काल","भक्तिकाल, आदिकाल, रीतिकाल, आधुनिक काल","आदिकाल, रीतिकाल, भक्तिकाल, आधुनिक काल","रीतिकाल, आदिकाल, भक्तिकाल, आधुनिक काल"],"o_hi":["आदिकाल, भक्तिकाल, रीतिकाल, आधुनिक काल","भक्तिकाल, आदिकाल, रीतिकाल, आधुनिक काल","आदिकाल, रीतिकाल, भक्तिकाल, आधुनिक काल","रीतिकाल, आदिकाल, भक्तिकाल, आधुनिक काल"],"a":0,"exp":"The standard sequence is Adikal (1050-1375), Bhaktikal (1375-1700), Ritikal (1700-1900), Adhunik Kal (1900 onwards).","exp_hi":"मानक क्रम है – आदिकाल (1050-1375), भक्तिकाल (1375-1700), रीतिकाल (1700-1900), आधुनिक काल (1900 से आगे)।","why":["यह क्रम भक्तिकाल को आदिकाल से पहले रखता है, जो गलत है; आदिकाल सबसे पहले आता है।","यह क्रम रीतिकाल को भक्तिकाल से पहले रखता है, जबकि रीतिकाल बाद में आता है।","यह क्रम रीतिकाल को सबसे पहले रखता है, जो ऐतिहासिक रूप से गलत है।"],"topic":"साहित्यिक काल","level":1,"mode":"standard"},{"q":"In the sentence 'मोहन ने पुस्तक पढ़ी', which word is the 'कर्म' (object)?","q_hi":"'मोहन ने पुस्तक पढ़ी' वाक्य में कौन सा शब्द 'कर्म' है?","o":["मोहन","ने","पुस्तक","पढ़ी"],"o_hi":["मोहन","ने","पुस्तक","पढ़ी"],"a":2,"exp":"In this sentence, 'मोहन' is the subject (कर्ता), 'ने' is the postposition, 'पुस्तक' is the object (कर्म) because the action of reading is done on it, and 'पढ़ी' is the verb.","exp_hi":"इस वाक्य में 'मोहन' कर्ता है, 'ने' कारक चिह्न है, 'पुस्तक' कर्म है क्योंकि पढ़ने की क्रिया उसी पर होती है, और 'पढ़ी' क्रिया है।","why":["'मोहन' कर्ता है, कर्म नहीं, क्योंकि वह क्रिया करने वाला है।","'ने' कारक चिह्न है, यह कर्म नहीं होता।","'पढ़ी' क्रिया है, कर्म नहीं।"],"topic":"व्याकरण – कारक","level":1,"mode":"standard"},{"q":"Which of the following poets is NOT associated with the Bhakti period?","q_hi":"निम्न में से कौन सा कवि भक्तिकाल से संबंधित नहीं है?","o":["तुलसीदास","सूरदास","कबीर","प्रेमचंद"],"o_hi":["तुलसीदास","सूरदास","कबीर","प्रेमचंद"],"a":3,"exp":"Premchand is a modern period writer (Adhunik Kal), known for novels and stories like 'Godan', while Tulsidas, Surdas, and Kabir are Bhakti period poets.","exp_hi":"प्रेमचंद आधुनिक काल के लेखक हैं, जिन्होंने 'गोदान' जैसे उपन्यास लिखे, जबकि तुलसीदास, सूरदास और कबीर भक्तिकाल के कवि हैं।","why":["तुलसीदास भक्तिकाल के सगुण भक्त कवि हैं, इसलिए वे सही नहीं।","सूरदास भी भक्तिकाल के सगुण भक्त कवि हैं।","कबीर भक्तिकाल के निर्गुण भक्त कवि हैं।"],"topic":"साहित्यिक काल – भक्तिकाल","level":1,"mode":"standard"},{"q":"Read the unseen passage and answer: 'सूर्योदय होते ही पक्षी चहचहाने लगे। किसान अपने खेतों की ओर चल पड़ा। बच्चे स्कूल जाने की तैयारी में लग गए।' What is the main idea of this passage?","q_hi":"अपठित गद्यांश पढ़कर उत्तर दीजिए: 'सूर्योदय होते ही पक्षी चहचहाने लगे। किसान अपने खेतों की ओर चल पड़ा। बच्चे स्कूल जाने की तैयारी में लग गए।' इस गद्यांश का मुख्य विचार क्या है?","o":["सूर्योदय के साथ दिन की शुरुआत होती है और सभी अपने काम में लग जाते हैं।","पक्षी सुबह चहचहाते हैं।","किसान खेतों में काम करते हैं।","बच्चे स्कूल जाते हैं।"],"o_hi":["सूर्योदय के साथ दिन की शुरुआत होती है और सभी अपने काम में लग जाते हैं।","पक्षी सुबह चहचहाते हैं।","किसान खेतों में काम करते हैं।","बच्चे स्कूल जाते हैं।"],"a":0,"exp":"The passage describes the beginning of a day with sunrise, and different people (birds, farmer, children) engaging in their respective activities, so the main idea is that sunrise starts the day and everyone gets busy.","exp_hi":"गद्यांश में सूर्योदय के साथ दिन की शुरुआत और विभिन्न लोगों (पक्षी, किसान, बच्चे) के अपने-अपने काम में लगने का वर्णन है, इसलिए मुख्य विचार यह है कि सूर्योदय के साथ दिन शुरू होता है और सभी व्यस्त हो जाते हैं।","why":["यह केवल एक विवरण है, पूरे गद्यांश का मुख्य विचार नहीं।","यह केवल किसान की गतिविधि है, पूरे गद्यांश का सार नहीं।","यह केवल बच्चों की गतिविधि है, पूरे गद्यांश का सार नहीं।"],"topic":"अपठित गद्यांश","level":2,"mode":"standard"},{"q":"Match the author with his/her famous work: 'महादेवी वर्मा' is known for which literary work?","q_hi":"लेखक को उनकी प्रसिद्ध रचना से मिलाइए: 'महादेवी वर्मा' किस साहित्यिक रचना के लिए प्रसिद्ध हैं?","o":["गोदान","कामायनी","मैला आँचल","नीरजा"],"o_hi":["गोदान","कामायनी","मैला आँचल","नीरजा"],"a":3,"exp":"Mahadevi Verma is a famous poetess of Chhayavad, and her poetry collection 'नीरजा' is very well-known. 'Godan' is by Premchand, 'Kamayani' by Jaishankar Prasad, and 'Maila Aanchal' by Phanishwar Nath Renu.","exp_hi":"महादेवी वर्मा छायावाद की प्रसिद्ध कवयित्री हैं, और उनका काव्य संग्रह 'नीरजा' बहुत प्रसिद्ध है। 'गोदान' प्रेमचंद की, 'कामायनी' जयशंकर प्रसाद की, और 'मैला आँचल' फणीश्वरनाथ रेणु की रचना है।","why":["'गोदान' प्रेमचंद की रचना है, महादेवी वर्मा की नहीं।","'कामायनी' जयशंकर प्रसाद की रचना है।","'मैला आँचल' फणीश्वरनाथ रेणु की रचना है।"],"topic":"लेखक और रचनाएँ","level":2,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-unseen-prose-poetry-mtjzwnlk","subject":"lang-hi","day":47,"level":1,"title":"Hindi Unseen Prose and Poetry","hi":"हिंदी अपठित गद्य और पद्य","concepts":[{"title":"Understanding Unseen Prose and Poetry","title_hi":"अपठित गद्य और पद्य को समझना","simple":"Unseen passages are new texts you read and answer questions about.","simple_hi":"अपठित गद्यांश नए पाठ होते हैं जिन्हें पढ़कर प्रश्नों के उत्तर देने होते हैं।","intro":"","points":["अपठित का अर्थ है 'न पढ़ा हुआ' – यह पाठ्यपुस्तक से नहीं होता।","गद्यांश में कहानी, निबंध या विचार होते हैं; पद्यांश में कविता।","प्रश्न आमतौर पर मुख्य भाव, कथन का अर्थ, और शीर्षक पर आधारित होते हैं।","उत्तर देने से पहले पूरा गद्यांश/पद्यांश ध्यान से कम से कम दो बार पढ़ें।","अक्सर उत्तर गद्यांश में ही छिपा होता है – उसे खोजें, रटें नहीं।"],"example":"एक छोटा गद्यांश: 'सुबह की सैर स्वास्थ्य के लिए लाभदायक है। यह शरीर को सक्रिय करती है और मन को प्रसन्न रखती है।' प्रश्न: सुबह की सैर किसके लिए लाभदायक है? उत्तर: स्वास्थ्य के लिए। (यह सीधे गद्यांश में है।)","trick":"पहले प्रश्न पढ़ें, फिर गद्यांश पढ़ें – इससे उत्तर ढूँढना आसान होता है।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"अपठित गद्यांश में अक्सर एक 'केंद्रीय भाव' होता है। कई बार विद्यार्थी अपने विचार मिला देते हैं, लेकिन उत्तर गद्यांश पर आधारित होना चाहिए। पद्यांश में कवि की भावना को समझना ज़रूरी है, शब्दों का शाब्दिक अर्थ नहीं।","body_hi":"अपठित गद्यांश में अक्सर एक 'केंद्रीय भाव' होता है। कई बार विद्यार्थी अपने विचार मिला देते हैं, लेकिन उत्तर गद्यांश पर आधारित होना चाहिए। पद्यांश में कवि की भावना को समझना ज़रूरी है, शब्दों का शाब्दिक अर्थ नहीं।"}}],"questions":[{"q":"Read the passage and answer: 'परिश्रम ही सफलता की कुंजी है। बिना परिश्रम के व्यक्ति जीवन में कुछ भी प्राप्त नहीं कर सकता।' The central idea of the passage is:","q_hi":"गद्यांश पढ़कर उत्तर दें: 'परिश्रम ही सफलता की कुंजी है। बिना परिश्रम के व्यक्ति जीवन में कुछ भी प्राप्त नहीं कर सकता।' गद्यांश का केंद्रीय भाव है:","o":["परिश्रम सफलता के लिए आवश्यक है","परिश्रम के बिना भी सफलता मिल सकती है","सफलता भाग्य पर निर्भर है","परिश्रम से थकान होती है"],"o_hi":["परिश्रम सफलता के लिए आवश्यक है","परिश्रम के बिना भी सफलता मिल सकती है","सफलता भाग्य पर निर्भर है","परिश्रम से थकान होती है"],"a":0,"exp":"The passage clearly states that hard work is the key to success, so option A matches the central idea.","exp_hi":"गद्यांश स्पष्ट रूप से कहता है कि परिश्रम सफलता की कुंजी है, इसलिए विकल्प A केंद्रीय भाव से मेल खाता है।","why":["यह गद्यांश के विपरीत है, क्योंकि गद्यांश कहता है कि बिना परिश्रम कुछ नहीं मिलता।","गद्यांश में भाग्य का कोई उल्लेख नहीं है, यह विचार गद्यांश से बाहर है।","गद्यांश में थकान की बात नहीं की गई है, यह अप्रासंगिक है।"],"topic":"अपठित गद्यांश","level":1,"mode":"standard"},{"q":"In the poem line: 'जीवन में सपने वही पूरे होते हैं, जो हिम्मत से देखे जाते हैं।' What does the poet mean?","q_hi":"पद्यांश की पंक्ति: 'जीवन में सपने वही पूरे होते हैं, जो हिम्मत से देखे जाते हैं।' कवि का क्या अभिप्राय है?","o":["केवल साहसी व्यक्ति के सपने पूरे होते हैं","सभी सपने पूरे होते हैं","सपने देखना बेकार है","सपने केवल रात में देखे जाते हैं"],"o_hi":["केवल साहसी व्यक्ति के सपने पूरे होते हैं","सभी सपने पूरे होते हैं","सपने देखना बेकार है","सपने केवल रात में देखे जाते हैं"],"a":0,"exp":"The line says dreams are fulfilled when seen with courage (himmat), so the poet means only courageous people's dreams come true.","exp_hi":"पंक्ति कहती है कि सपने हिम्मत से देखने पर पूरे होते हैं, इसलिए कवि का अर्थ है कि केवल साहसी लोगों के सपने पूरे होते हैं।","why":["यह अतिशयोक्ति है, कवि सभी सपनों की बात नहीं कर रहा।","कवि सपनों को बेकार नहीं कह रहा, बल्कि हिम्मत पर ज़ोर दे रहा है।","सपने का अर्थ यहाँ आकांक्षा है, रात के सपने नहीं।"],"topic":"अपठित पद्यांश","level":2,"mode":"standard"},{"q":"Given the passage: 'पेड़ हमें फल, छाया और ऑक्सीजन देते हैं। वे पर्यावरण को शुद्ध रखते हैं।' Which title best suits the passage?","q_hi":"गद्यांश: 'पेड़ हमें फल, छाया और ऑक्सीजन देते हैं। वे पर्यावरण को शुद्ध रखते हैं।' इस गद्यांश के लिए सबसे उपयुक्त शीर्षक क्या होगा?","o":["पेड़ों का महत्व","पेड़ों की देखभाल","वनों की कटाई","फलों के प्रकार"],"o_hi":["पेड़ों का महत्व","पेड़ों की देखभाल","वनों की कटाई","फलों के प्रकार"],"a":0,"exp":"The passage talks about what trees give us and how they purify the environment, so 'Importance of Trees' is the best title.","exp_hi":"गद्यांश में पेड़ों से मिलने वाले लाभ और पर्यावरण शुद्धिकरण की बात है, इसलिए 'पेड़ों का महत्व' सबसे उपयुक्त शीर्षक है।","why":["गद्यांश में देखभाल के बारे में कुछ नहीं कहा गया है।","गद्यांश में वनों की कटाई का कोई उल्लेख नहीं है।","गद्यांश केवल फलों के बारे में नहीं है, बल्कि छाया और ऑक्सीजन की भी बात है।"],"topic":"अपठित गद्यांश","level":1,"mode":"standard"},{"q":"Read the poem: 'चिड़िया दाना चुगती है, पेड़ पर बैठकर गाती है।' Which word in the poem is a verb?","q_hi":"कविता पढ़ें: 'चिड़िया दाना चुगती है, पेड़ पर बैठकर गाती है।' कविता में कौन-सा शब्द क्रिया है?","o":["चिड़िया","दाना","पेड़","गाती"],"o_hi":["चिड़िया","दाना","पेड़","गाती"],"a":3,"exp":"'गाती' is the verb because it shows the action of singing.","exp_hi":"'गाती' क्रिया है क्योंकि यह गाने की क्रिया को दर्शाता है।","why":["'चिड़िया' संज्ञा है, क्रिया नहीं।","'दाना' संज्ञा है, क्रिया नहीं।","'पेड़' संज्ञा है, क्रिया नहीं।"],"topic":"अपठित पद्यांश","level":1,"mode":"standard"},{"q":"Passage: 'अनुशासन जीवन का आधार है। यह व्यक्ति को समय पर कार्य करना सिखाता है।' What does the passage say discipline teaches?","q_hi":"गद्यांश: 'अनुशासन जीवन का आधार है। यह व्यक्ति को समय पर कार्य करना सिखाता है।' गद्यांश के अनुसार अनुशासन क्या सिखाता है?","o":["समय पर कार्य करना","दूसरों की मदद करना","कठिन परिश्रम करना","सत्य बोलना"],"o_hi":["समय पर कार्य करना","दूसरों की मदद करना","कठिन परिश्रम करना","सत्य बोलना"],"a":0,"exp":"The passage explicitly states that discipline teaches a person to do work on time.","exp_hi":"गद्यांश स्पष्ट रूप से कहता है कि अनुशासन व्यक्ति को समय पर कार्य करना सिखाता है।","why":["गद्यांश में मदद करने की बात नहीं है।","गद्यांश में परिश्रम की बात नहीं है।","गद्यांश में सत्य बोलने की बात नहीं है।"],"topic":"अपठित गद्यांश","level":1,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-grammar-practice-mtjzwrie","subject":"lang-hi","day":46,"level":1,"title":"Hindi Grammar Practice","hi":"हिंदी व्याकरण अभ्यास","concepts":[{"title":"Noun and Gender","title_hi":"संज्ञा और लिंग","simple":"A noun is a naming word; in Hindi, nouns have genders (masculine or feminine).","simple_hi":"संज्ञा नाम बताने वाला शब्द है; हिंदी में संज्ञाओं के लिंग होते हैं (पुल्लिंग या स्त्रीलिंग)।","intro":"","points":["संज्ञा किसी व्यक्ति, वस्तु, स्थान या भाव के नाम को कहते हैं। (A noun names a person, thing, place, or feeling.)","हिंदी में दो लिंग होते हैं: पुल्लिंग (masculine) और स्त्रीलिंग (feminine)।","लिंग बदलने के नियम: कई बार अंतिम अक्षर बदलने से लिंग बदल जाता है, जैसे 'लड़का' (पुल्लिंग) → 'लड़की' (स्त्रीलिंग)।","कुछ शब्दों के लिंग नियम से नहीं बदलते, उन्हें रटना पड़ता है, जैसे 'मित्र' (पुल्लिंग) और 'सखी' (स्त्रीलिंग)।","लिंग पहचानने से वाक्य में क्रिया और विशेषण का सही प्रयोग होता है।"],"example":"जैसे: 'बच्चा स्कूल जाता है' – यहाँ 'बच्चा' पुल्लिंग है, इसलिए क्रिया 'जाता' (पुल्लिंग) आई। यदि 'बच्ची' होती, तो क्रिया 'जाती' होती। (Example: 'The boy goes to school' – 'बच्चा' is masculine, so verb 'जाता' is used. If it were 'बच्ची', the verb would be 'जाती'.)","trick":"याद रखें: 'आ' अंत वाले कई शब्द पुल्लिंग होते हैं (जैसे लड़का, बेटा), और 'ई' अंत वाले कई शब्द स्त्रीलिंग (जैसे लड़की, बेटी)। लेकिन अपवाद भी हैं, जैसे 'कवि' पुल्लिंग है। (Remember: words ending in 'आ' are often masculine (like लड़का), and 'ई' often feminine (like लड़की), but there are exceptions like 'कवि'.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"हिंदी व्याकरण में लिंग केवल संज्ञा तक सीमित नहीं है; यह सर्वनाम, विशेषण और क्रिया को भी प्रभावित करता है। परीक्षा में अक्सर ऐसे शब्द पूछे जाते हैं जिनके लिंग नियम से नहीं बदलते, जैसे 'पंडित' (पुल्लिंग) और 'पंडिताइन' (स्त्रीलिंग) – यहाँ प्रत्यय जुड़ता है। कुछ शब्द जैसे 'अध्यापक' और 'अध्यापिका' में मूल शब्द बदल जाता है। इसलिए लिंग पहचानने के लिए शब्द के अंत और प्रचलन दोनों पर ध्यान देना चाहिए।","body_hi":"हिंदी व्याकरण में लिंग केवल संज्ञा तक सीमित नहीं है; यह सर्वनाम, विशेषण और क्रिया को भी प्रभावित करता है। परीक्षा में अक्सर ऐसे शब्द पूछे जाते हैं जिनके लिंग नियम से नहीं बदलते, जैसे 'पंडित' (पुल्लिंग) और 'पंडिताइन' (स्त्रीलिंग) – यहाँ प्रत्यय जुड़ता है। कुछ शब्द जैसे 'अध्यापक' और 'अध्यापिका' में मूल शब्द बदल जाता है। इसलिए लिंग पहचानने के लिए शब्द के अंत और प्रचलन दोनों पर ध्यान देना चाहिए।"}}],"questions":[{"q":"Choose the correct feminine form of 'लेखक' (writer):","q_hi":"'लेखक' का सही स्त्रीलिंग रूप चुनिए:","o":["लेखिका","लेखकी","लेखका","लेखनी"],"o_hi":["लेखिका","लेखकी","लेखका","लेखनी"],"a":0,"exp":"'लेखक' का स्त्रीलिंग 'लेखिका' होता है।","exp_hi":"'लेखक' का स्त्रीलिंग 'लेखिका' होता है।","why":["'लेखकी' प्रचलित नहीं है, यह गलत रूप है।","'लेखका' गलत है, सही प्रत्यय 'इका' है।","'लेखनी' का अर्थ 'pen' होता है, यह स्त्रीलिंग संज्ञा है लेकिन लेखक का स्त्रीलिंग नहीं।"],"topic":"लिंग परिवर्तन","level":1,"mode":"standard"},{"q":"Which sentence is grammatically correct?","q_hi":"कौन सा वाक्य व्याकरण की दृष्टि से सही है?","o":["बच्चा स्कूल जाती है।","बच्ची स्कूल जाता है।","बच्चा स्कूल जाता है।","बच्ची स्कूल जाते हैं।"],"o_hi":["बच्चा स्कूल जाती है।","बच्ची स्कूल जाता है।","बच्चा स्कूल जाता है।","बच्ची स्कूल जाते हैं।"],"a":2,"exp":"'बच्चा' पुल्लिंग है, इसलिए क्रिया 'जाता' सही है।","exp_hi":"'बच्चा' पुल्लिंग है, इसलिए क्रिया 'जाता' सही है।","why":["विकल्प A में 'बच्चा' (पुल्लिंग) के साथ 'जाती' (स्त्रीलिंग) का प्रयोग गलत है।","विकल्प B में 'बच्ची' (स्त्रीलिंग) के साथ 'जाता' (पुल्लिंग) गलत है।","विकल्प D में 'बच्ची' एकवचन है, 'जाते हैं' बहुवचन है, इसलिए असंगत।"],"topic":"लिंग-क्रिया समझौता","level":2,"mode":"standard"},{"q":"What is the gender of the word 'मित्र'?","q_hi":"'मित्र' शब्द का लिंग क्या है?","o":["स्त्रीलिंग","पुल्लिंग","नपुंसकलिंग","उभयलिंग"],"o_hi":["स्त्रीलिंग","पुल्लिंग","नपुंसकलिंग","उभयलिंग"],"a":1,"exp":"'मित्र' पुल्लिंग है। इसका स्त्रीलिंग 'सखी' या 'मित्रा' होता है।","exp_hi":"'मित्र' पुल्लिंग है। इसका स्त्रीलिंग 'सखी' या 'मित्रा' होता है।","why":["'मित्र' पुल्लिंग है, स्त्रीलिंग नहीं।","हिंदी में नपुंसकलिंग नहीं होता, केवल पुल्लिंग और स्त्रीलिंग होते हैं।","'उभयलिंग' शब्द प्रचलित नहीं है; कुछ शब्द दोनों लिंगों के लिए प्रयुक्त होते हैं, लेकिन 'मित्र' नहीं।"],"topic":"लिंग पहचान","level":1,"mode":"standard"},{"q":"Choose the correct feminine form of 'पंडित' (scholar):","q_hi":"'पंडित' का सही स्त्रीलिंग रूप चुनिए:","o":["पंडिता","पंडितिन","पंडिताई","पंडितानी"],"o_hi":["पंडिता","पंडितिन","पंडिताई","पंडितानी"],"a":3,"exp":"'पंडित' का स्त्रीलिंग 'पंडितानी' होता है। यह प्रचलित रूप है।","exp_hi":"'पंडित' का स्त्रीलिंग 'पंडितानी' होता है। यह प्रचलित रूप है।","why":["'पंडिता' कुछ संदर्भों में प्रयोग हो सकता है, लेकिन मानक स्त्रीलिंग 'पंडितानी' है।","'पंडितिन' गलत है, ऐसा प्रत्यय नहीं लगता।","'पंडिताई' का अर्थ 'पांडित्य' होता है, यह स्त्रीलिंग संज्ञा नहीं।"],"topic":"लिंग परिवर्तन (विशेष)","level":2,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-prominent-authors-poets-works-mtjzx2q1","subject":"lang-hi","day":48,"level":1,"title":"Hindi Literature: Prominent Authors, Poets & Works","hi":"हिन्दी साहित्य: प्रमुख लेखक, कवि एवं रचनाएँ","concepts":[{"title":"Famous Hindi Writers and Their Works","title_hi":"प्रसिद्ध हिन्दी लेखक और उनकी रचनाएँ","simple":"Many great writers wrote poems and stories in Hindi, and we remember them by their famous books.","simple_hi":"कई महान लेखकों ने हिन्दी में कविताएँ और कहानियाँ लिखीं, और हम उन्हें उनकी प्रसिद्ध पुस्तकों से याद करते हैं।","intro":"","points":["मुंशी प्रेमचंद को 'कथा सम्राट' कहा जाता है; उनकी प्रसिद्ध रचनाएँ हैं 'गोदान', 'गबन', 'निर्मला'। (Munshi Premchand is called 'Katha Samrat'; his famous works are 'Godan', 'Gaban', 'Nirmala'.)","जयशंकर प्रसाद छायावादी युग के प्रमुख कवि थे; उनकी प्रसिद्ध कृति है 'कामायनी'। (Jaishankar Prasad was a leading poet of the Chhayavaad era; his famous work is 'Kamayani'.)","मैथिलीशरण गुप्त को 'राष्ट्रकवि' कहा जाता है; उनकी प्रसिद्ध रचना है 'भारत-भारती'। (Maithilisharan Gupt is called 'Rashtrakavi'; his famous work is 'Bharat-Bharati'.)","सूरदास कृष्ण भक्त कवि थे; उन्होंने 'सूरसागर' की रचना की। (Surdas was a Krishna devotee poet; he composed 'Sursagar'.)","तुलसीदास ने 'रामचरितमानस' लिखी, जो राम की कथा पर आधारित है। (Tulsidas wrote 'Ramcharitmanas', based on the story of Rama.)","महादेवी वर्मा छायावादी युग की प्रसिद्ध कवयित्री थीं; उन्हें 'आधुनिक मीरा' कहा जाता है। (Mahadevi Verma was a famous poetess of the Chhayavaad era; she is called 'Modern Meera'.)"],"example":"उदाहरण के लिए, मुंशी प्रेमचंद की 'गोदान' कहानी एक गरीब किसान 'होरी' की है। प्रेमचंद ने गाँव की ज़िंदगी और किसानों की समस्याओं को दिखाया। इसी तरह, जयशंकर प्रसाद की 'कामायनी' एक महाकाव्य है जो मनु और श्रद्धा की प्रेम कथा है। (For example, Munshi Premchand's 'Godan' is the story of a poor farmer 'Hori'. Premchand showed village life and farmers' problems. Similarly, Jaishankar Prasad's 'Kamayani' is an epic that is the love story of Manu and Shraddha.)","trick":"याद रखने की तरकीब: 'प्रेमचंद गोदान में गरीब किसान होरी की कथा लिखते हैं' – 'गोदान' और 'होरी' दोनों 'ग' और 'ह' से शुरू होते हैं। (Memory trick: 'Premchand writes the story of poor farmer Hori in Godan' – both 'Godan' and 'Hori' start with similar sounds.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"परीक्षा में अक्सर लेखक और उनकी रचनाओं का मिलान पूछा जाता है। ध्यान रखें कि प्रेमचंद का जन्म 1880 में हुआ था और वे यथार्थवादी लेखक थे। जयशंकर प्रसाद, सूर्यकांत त्रिपाठी 'निराला', सुमित्रानंदन पंत और महादेवी वर्मा छायावादी युग के चार प्रमुख स्तंभ हैं। मैथिलीशरण गुप्त खड़ी बोली के पहले महत्वपूर्ण कवि माने जाते हैं। कबीरदास निर्गुण भक्ति धारा के कवि थे, और रहीम नीति के दोहे लिखने के लिए प्रसिद्ध हैं। (In exams, matching authors to their works is often asked. Remember that Premchand was born in 1880 and was a realist writer. Jaishankar Prasad, Suryakant Tripathi 'Nirala', Sumitranandan Pant, and Mahadevi Verma are the four pillars of the Chhayavaad era. Maithilisharan Gupt is considered the first important poet of Khadi Boli. Kabirdas was a poet of the Nirgun Bhakti tradition, and Rahim is famous for his couplets on ethics.)","body_hi":"परीक्षा में अक्सर लेखक और उनकी रचनाओं का मिलान पूछा जाता है। ध्यान रखें कि प्रेमचंद का जन्म 1880 में हुआ था और वे यथार्थवादी लेखक थे। जयशंकर प्रसाद, सूर्यकांत त्रिपाठी 'निराला', सुमित्रानंदन पंत और महादेवी वर्मा छायावादी युग के चार प्रमुख स्तंभ हैं। मैथिलीशरण गुप्त खड़ी बोली के पहले महत्वपूर्ण कवि माने जाते हैं। कबीरदास निर्गुण भक्ति धारा के कवि थे, और रहीम नीति के दोहे लिखने के लिए प्रसिद्ध हैं। (In exams, matching authors to their works is often asked. Remember that Premchand was born in 1880 and was a realist writer. Jaishankar Prasad, Suryakant Tripathi 'Nirala', Sumitranandan Pant, and Mahadevi Verma are the four pillars of the Chhayavaad era. Maithilisharan Gupt is considered the first important poet of Khadi Boli. Kabirdas was a poet of the Nirgun Bhakti tradition, and Rahim is famous for his couplets on ethics.)"}}],"questions":[{"q":"Who is known as 'Katha Samrat' (Emperor of Stories) in Hindi literature?","q_hi":"हिन्दी साहित्य में 'कथा सम्राट' के नाम से कौन जाने जाते हैं?","o":["Jaishankar Prasad","Munshi Premchand","Maithilisharan Gupt","Mahadevi Verma"],"o_hi":["जयशंकर प्रसाद","मुंशी प्रेमचंद","मैथिलीशरण गुप्त","महादेवी वर्मा"],"a":1,"exp":"Munshi Premchand is known as 'Katha Samrat' because he wrote many famous stories and novels depicting social realism.","exp_hi":"मुंशी प्रेमचंद को 'कथा सम्राट' कहा जाता है क्योंकि उन्होंने सामाजिक यथार्थ को दर्शाने वाली अनेक प्रसिद्ध कहानियाँ और उपन्यास लिखे।","why":["जयशंकर प्रसाद छायावादी युग के कवि थे, उन्हें 'कामायनी' जैसी रचनाओं के लिए जाना जाता है, कथा सम्राट नहीं।","मैथिलीशरण गुप्त 'राष्ट्रकवि' कहलाते हैं, कथा सम्राट नहीं।","महादेवी वर्मा 'आधुनिक मीरा' कहलाती हैं, वे कवयित्री हैं, कथा सम्राट नहीं।"],"topic":"Author's title","level":1,"mode":"standard"},{"q":"Which work is written by Jaishankar Prasad?","q_hi":"जयशंकर प्रसाद द्वारा रचित कृति कौन-सी है?","o":["Godan","Kamayani","Bharat-Bharati","Sursagar"],"o_hi":["गोदान","कामायनी","भारत-भारती","सूरसागर"],"a":1,"exp":"'Kamayani' is a famous epic (mahakavya) written by Jaishankar Prasad, based on the story of Manu and Shraddha.","exp_hi":"'कामायनी' जयशंकर प्रसाद द्वारा रचित प्रसिद्ध महाकाव्य है, जो मनु और श्रद्धा की कथा पर आधारित है।","why":["'गोदान' मुंशी प्रेमचंद की रचना है, जयशंकर प्रसाद की नहीं।","'भारत-भारती' मैथिलीशरण गुप्त की रचना है, जयशंकर प्रसाद की नहीं।","'सूरसागर' सूरदास की रचना है, जयशंकर प्रसाद की नहीं।"],"topic":"Author-work matching","level":1,"mode":"standard"},{"q":"Who is the author of 'Ramcharitmanas'?","q_hi":"'रामचरितमानस' के रचयिता कौन हैं?","o":["Surdas","Tulsidas","Kabir","Rahim"],"o_hi":["सूरदास","तुलसीदास","कबीर","रहीम"],"a":1,"exp":"Tulsidas wrote 'Ramcharitmanas' in Awadhi language, which narrates the story of Lord Rama.","exp_hi":"तुलसीदास ने अवधी भाषा में 'रामचरितमानस' की रचना की, जिसमें भगवान राम की कथा वर्णित है।","why":["सूरदास ने 'सूरसागर' की रचना की, जो कृष्ण भक्ति से संबंधित है, रामचरितमानस नहीं।","कबीर ने दोहे और साखियाँ लिखीं, रामचरितमानस नहीं।","रहीम ने नीति के दोहे लिखे, रामचरितमानस नहीं।"],"topic":"Author-work matching","level":1,"mode":"standard"},{"q":"Which poet is known as 'Rashtrakavi' (National Poet)?","q_hi":"किस कवि को 'राष्ट्रकवि' के नाम से जाना जाता है?","o":["Suryakant Tripathi 'Nirala'","Sumitranandan Pant","Maithilisharan Gupt","Mahadevi Verma"],"o_hi":["सूर्यकांत त्रिपाठी 'निराला'","सुमित्रानंदन पंत","मैथिलीशरण गुप्त","महादेवी वर्मा"],"a":2,"exp":"Maithilisharan Gupt is called 'Rashtrakavi' because his poetry inspired nationalism, especially his work 'Bharat-Bharati'.","exp_hi":"मैथिलीशरण गुप्त को 'राष्ट्रकवि' कहा जाता है क्योंकि उनकी कविताओं ने राष्ट्रीयता की भावना जगाई, विशेष रूप से उनकी रचना 'भारत-भारती'।","why":["निराला छायावादी कवि थे, उन्हें 'राष्ट्रकवि' नहीं कहा जाता।","सुमित्रानंदन पंत छायावादी कवि थे, उन्हें 'राष्ट्रकवि' नहीं कहा जाता।","महादेवी वर्मा को 'आधुनिक मीरा' कहा जाता है, 'राष्ट्रकवि' नहीं।"],"topic":"Author's title","level":1,"mode":"standard"},{"q":"Which of the following pairs (Author - Work) is correctly matched?","q_hi":"निम्नलिखित में से कौन-सा युग्म (लेखक - रचना) सही सुमेलित है?","o":["Surdas - Ramcharitmanas","Tulsidas - Sursagar","Kabir - Bijak","Rahim - Kamayani"],"o_hi":["सूरदास - रामचरितमानस","तुलसीदास - सूरसागर","कबीर - बीजक","रहीम - कामायनी"],"a":2,"exp":"Kabir's compositions are compiled in 'Bijak'. This is a correct match.","exp_hi":"कबीर की रचनाओं का संग्रह 'बीजक' में है। यह सही सुमेल है।","why":["सूरदास ने 'सूरसागर' लिखा, रामचरितमानस नहीं।","तुलसीदास ने 'रामचरितमानस' लिखा, सूरसागर नहीं।","रहीम ने 'कामायनी' नहीं लिखी; कामायनी जयशंकर प्रसाद की रचना है।"],"topic":"Author-work matching","level":2,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-unseen-prose-poetry-mtjzx8ne","subject":"lang-hi","day":47,"level":1,"title":"Hindi Unseen Prose and Poetry","hi":"हिंदी अपठित गद्य और पद्य","concepts":[{"title":"Understanding Unseen Passages","title_hi":"अपठित गद्यांश को समझना","simple":"When you read a new passage and answer questions about it, you are solving an unseen passage.","simple_hi":"जब आप कोई नया गद्यांश पढ़कर उसके प्रश्नों के उत्तर देते हैं, तो उसे अपठित गद्यांश कहते हैं।","intro":"","points":["अपठित का अर्थ है 'न पढ़ा हुआ' – यह passage परीक्षा में पहली बार दिखता है। / 'Unseen' means 'not read before' – the passage appears for the first time in the exam.","उत्तर हमेशा passage में दिए गए विचारों पर आधारित होते हैं, बाहरी ज्ञान पर नहीं। / Answers are always based on the ideas given in the passage, not on outside knowledge.","गद्यांश (prose) में कहानी, विचार या जानकारी होती है; पद्यांश (poetry) में भाव और लय होती है। / Prose has story, ideas, or information; poetry has emotion and rhythm.","प्रश्न पूछे जाते हैं: मुख्य विचार, शीर्षक, भाव, क्रिया-विशेषण, संज्ञा आदि। / Questions are asked about: main idea, title, emotion, adverbs, nouns, etc.","पहले पूरा passage पढ़ें, फिर प्रश्न देखें और passage में ढूँढें। / First read the whole passage, then see the questions and search in the passage."],"example":"उदाहरण: एक गद्यांश में लिखा है, 'सूर्योदय होते ही पक्षी चहचहाने लगे।' प्रश्न: पक्षी कब चहचहाते हैं? उत्तर: सूर्योदय होते ही। यह उत्तर सीधे passage से मिलता है। / Example: A prose passage says, 'As soon as the sun rose, the birds began to chirp.' Question: When do the birds chirp? Answer: As soon as the sun rises. This answer is directly from the passage.","trick":"ट्रिक: 'पहले पढ़ो, फिर खोजो' – passage को एक बार पढ़ो, फिर प्रश्न पढ़कर passage में उत्तर को रेखांकित करो। / Trick: 'Read first, then search' – read the passage once, then read the question and underline the answer in the passage.","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"अपठित गद्यांश में अक्सर ऐसे प्रश्न होते हैं जो शब्दों के अर्थ (synonyms/antonyms) या वाक्यों के भाव पूछते हैं। कई बार passage का शीर्षक सुझाना होता है, जो कि passage के मुख्य विचार पर आधारित होता है। छात्र अक्सर बाहरी जानकारी से उत्तर देने की गलती करते हैं, जबकि सही उत्तर passage में ही छिपा होता है। इसलिए passage को ध्यान से पढ़ना और हर शब्द पर गौर करना आवश्यक है। / In unseen prose, questions often ask for meanings of words (synonyms/antonyms) or the essence of sentences. Sometimes you have to suggest a title, which is based on the main idea. Students often make the mistake of answering from outside knowledge, while the correct answer is hidden in the passage. So careful reading and attention to every word is essential.","body_hi":"अपठित गद्यांश में अक्सर ऐसे प्रश्न होते हैं जो शब्दों के अर्थ (synonyms/antonyms) या वाक्यों के भाव पूछते हैं। कई बार passage का शीर्षक सुझाना होता है, जो कि passage के मुख्य विचार पर आधारित होता है। छात्र अक्सर बाहरी जानकारी से उत्तर देने की गलती करते हैं, जबकि सही उत्तर passage में ही छिपा होता है। इसलिए passage को ध्यान से पढ़ना और हर शब्द पर गौर करना आवश्यक है। / In unseen prose, questions often ask for meanings of words (synonyms/antonyms) or the essence of sentences. Sometimes you have to suggest a title, which is based on the main idea. Students often make the mistake of answering from outside knowledge, while the correct answer is hidden in the passage. So careful reading and attention to every word is essential."}}],"questions":[{"q":"Read the following passage and answer the question: 'परिश्रम ही सफलता की कुंजी है। बिना परिश्रम के कोई भी व्यक्ति ऊँचाई को नहीं छू सकता। जो विद्यार्थी नियमित पढ़ाई करता है, वही परीक्षा में अच्छे अंक लाता है।' उपर्युक्त गद्यांश का मुख्य विचार क्या है?","q_hi":"निम्नलिखित गद्यांश को पढ़कर प्रश्न का उत्तर दीजिए: 'परिश्रम ही सफलता की कुंजी है। बिना परिश्रम के कोई भी व्यक्ति ऊँचाई को नहीं छू सकता। जो विद्यार्थी नियमित पढ़ाई करता है, वही परीक्षा में अच्छे अंक लाता है।' उपर्युक्त गद्यांश का मुख्य विचार क्या है?","o":["परीक्षा में अच्छे अंक लाना","परिश्रम का महत्व","विद्यार्थी का जीवन","ऊँचाई को छूना"],"o_hi":["परीक्षा में अच्छे अंक लाना","परिश्रम का महत्व","विद्यार्थी का जीवन","ऊँचाई को छूना"],"a":1,"exp":"The passage repeatedly emphasizes that hard work is the key to success and without it no one can achieve heights. So the main idea is the importance of hard work.","exp_hi":"गद्यांश में बार-बार कहा गया है कि परिश्रम सफलता की कुंजी है और बिना परिश्रम कोई ऊँचाई नहीं छू सकता। अतः मुख्य विचार परिश्रम का महत्व है।","why":["यह विकल्प गद्यांश का एक उदाहरण है, मुख्य विचार नहीं।","यह गद्यांश में विद्यार्थी का उल्लेख है, लेकिन मुख्य विचार परिश्रम है।","यह गद्यांश में आया वाक्यांश है, पर मुख्य विचार नहीं।"],"topic":"अपठित गद्यांश – मुख्य विचार","level":1,"mode":"standard"},{"q":"Read the following poem and answer: 'चिड़िया चोंच में तिनका लेकर, घोंसला बनाती है। परिश्रम से वह अपने बच्चों को, सुरक्षित रख पाती है।' इस पद्यांश में चिड़िया के किस गुण की ओर संकेत किया गया है?","q_hi":"निम्नलिखित पद्यांश को पढ़कर उत्तर दीजिए: 'चिड़िया चोंच में तिनका लेकर, घोंसला बनाती है। परिश्रम से वह अपने बच्चों को, सुरक्षित रख पाती है।' इस पद्यांश में चिड़िया के किस गुण की ओर संकेत किया गया है?","o":["सुंदरता","परिश्रम","उड़ान","चहचहाहट"],"o_hi":["सुंदरता","परिश्रम","उड़ान","चहचहाहट"],"a":1,"exp":"The poem says the bird builds a nest with straw and through hard work keeps its children safe. So the quality highlighted is hard work.","exp_hi":"कविता कहती है कि चिड़िया तिनका लेकर घोंसला बनाती है और परिश्रम से अपने बच्चों को सुरक्षित रखती है। अतः संकेत परिश्रम गुण की ओर है।","why":["सुंदरता का उल्लेख कविता में नहीं है।","उड़ान का उल्लेख कविता में नहीं है।","चहचहाहट का उल्लेख कविता में नहीं है।"],"topic":"अपठित पद्यांश – भाव","level":1,"mode":"standard"},{"q":"Read the passage: 'गाँव में एक तालाब था। गर्मियों में वह सूख जाता था। तब ग्रामीणों को पानी के लिए दूर जाना पड़ता था।' 'ग्रामीणों' शब्द का अर्थ क्या है?","q_hi":"गद्यांश पढ़िए: 'गाँव में एक तालाब था। गर्मियों में वह सूख जाता था। तब ग्रामीणों को पानी के लिए दूर जाना पड़ता था।' 'ग्रामीणों' शब्द का अर्थ क्या है?","o":["शहर के लोग","गाँव के लोग","पशु-पक्षी","बच्चे"],"o_hi":["शहर के लोग","गाँव के लोग","पशु-पक्षी","बच्चे"],"a":1,"exp":"The word 'ग्रामीण' is derived from 'ग्राम' meaning village, so it refers to village people.","exp_hi":"'ग्रामीण' शब्द 'ग्राम' से बना है जिसका अर्थ गाँव है, अतः इसका अर्थ गाँव के लोग हैं।","why":["'ग्रामीण' का अर्थ शहर के लोग नहीं होता।","'ग्रामीण' मनुष्यों के लिए प्रयुक्त होता है, पशु-पक्षियों के लिए नहीं।","'ग्रामीण' का अर्थ सभी गाँव के निवासी हैं, केवल बच्चे नहीं।"],"topic":"अपठित गद्यांश – शब्दार्थ","level":2,"mode":"standard"},{"q":"Read the poem: 'बादल आए, बरसे पानी, धरती ने भर ली अंगड़ाई।' 'अंगड़ाई' का भाव है:","q_hi":"पद्यांश पढ़िए: 'बादल आए, बरसे पानी, धरती ने भर ली अंगड़ाई।' 'अंगड़ाई' का भाव है:","o":["थकान","प्रसन्नता और ताजगी","नींद","दुख"],"o_hi":["थकान","प्रसन्नता और ताजगी","नींद","दुख"],"a":1,"exp":"The earth stretches after rain, which symbolizes happiness and freshness, like a person stretching after a good rest.","exp_hi":"वर्षा के बाद धरती की अंगड़ाई प्रसन्नता और ताजगी का प्रतीक है, जैसे आराम के बाद व्यक्ति अंगड़ाई लेता है।","why":["अंगड़ाई थकान का संकेत नहीं, बल्कि ताजगी का है।","अंगड़ाई नींद का भाव नहीं देती।","अंगड़ाई दुख का भाव नहीं है।"],"topic":"अपठित पद्यांश – भावार्थ","level":2,"mode":"standard"},{"q":"Read the passage: 'स्वच्छता का महत्व हमारे जीवन में बहुत है। यह न केवल शारीरिक स्वास्थ्य के लिए आवश्यक है, बल्कि मानसिक शांति भी देती है।' इस गद्यांश के लिए उपयुक्त शीर्षक चुनिए।","q_hi":"गद्यांश पढ़िए: 'स्वच्छता का महत्व हमारे जीवन में बहुत है। यह न केवल शारीरिक स्वास्थ्य के लिए आवश्यक है, बल्कि मानसिक शांति भी देती है।' इस गद्यांश के लिए उपयुक्त शीर्षक चुनिए।","o":["शारीरिक स्वास्थ्य","मानसिक शांति","स्वच्छता का महत्व","जीवन का आधार"],"o_hi":["शारीरिक स्वास्थ्य","मानसिक शांति","स्वच्छता का महत्व","जीवन का आधार"],"a":2,"exp":"The passage talks about the importance of cleanliness, so the most suitable title is 'Importance of Cleanliness'.","exp_hi":"गद्यांश स्वच्छता के महत्व पर केंद्रित है, इसलिए सबसे उपयुक्त शीर्षक 'स्वच्छता का महत्व' है।","why":["यह गद्यांश का एक पहलू है, पूरा विषय नहीं।","यह भी एक पहलू है, पूरा विषय नहीं।","यह शीर्षक सामान्य है, पर गद्यांश में स्वच्छता पर जोर है, इसलिए यह कम उपयुक्त है।"],"topic":"अपठित गद्यांश – शीर्षक","level":2,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-revision-practice-mtjzxgu2","subject":"lang-hi","day":49,"level":1,"title":"Hindi Language & Literature Revision and Practice","hi":"हिंदी भाषा एवं साहित्य – पुनरावृत्ति एवं अभ्यास","concepts":[{"title":"Hindi Grammar and Literature Basics","title_hi":"हिंदी व्याकरण और साहित्य की मूल बातें","simple":"Hindi grammar is like the rules of a game, and literature is the beautiful stories and poems we play with.","simple_hi":"हिंदी व्याकरण खेल के नियमों जैसा है, और साहित्य वे सुंदर कहानियाँ और कविताएँ हैं जिनसे हम खेलते हैं।","intro":"","points":["संज्ञा किसी व्यक्ति, वस्तु, स्थान या भाव का नाम है। (Noun is the name of a person, thing, place, or feeling.)","सर्वनाम वह शब्द है जो संज्ञा के स्थान पर प्रयोग होता है, जैसे 'वह', 'मैं'। (Pronoun replaces a noun, like 'he', 'I'.)","क्रिया काम को दर्शाती है, जैसे 'दौड़ना', 'खाना'। (Verb shows action.)","विशेषण संज्ञा या सर्वनाम की विशेषता बताता है, जैसे 'सुंदर', 'बड़ा'। (Adjective describes a noun or pronoun.)","मुहावरे वाक्यांश होते हैं जिनका अर्थ शब्दों के सामान्य अर्थ से अलग होता है। (Idioms have a figurative meaning.)","प्रमुख साहित्यकार: प्रेमचंद (कहानीकार), सूरदास (भक्तिकाल), मैथिलीशरण गुप्त (राष्ट्रकवि)।"],"example":"वाक्य: 'राम ने आम खाया।' इसमें 'राम' संज्ञा है, 'ने' कारक चिह्न है, 'आम' कर्म है, और 'खाया' क्रिया है। यदि हम 'राम' की जगह 'वह' लिखें, तो 'वह' सर्वनाम बन जाता है। (In the sentence 'Ram ate a mango', 'Ram' is a noun, 'ate' is the verb, and 'mango' is the object. If we replace 'Ram' with 'He', it becomes a pronoun.)","trick":"संज्ञा और सर्वनाम याद रखने के लिए सोचें: 'संज्ञा' = नाम (जैसे 'गीता'), 'सर्वनाम' = सब के नाम की जगह (जैसे 'वह')। (To remember noun vs pronoun: Noun is a name, pronoun stands in place of a name.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"हिंदी व्याकरण में वचन (singular/plural), लिंग (gender), काल (tense) और कारक (case) महत्वपूर्ण हैं। परीक्षा में अक्सर त्रुटि-निर्णय (error spotting) या वाक्य-शुद्धि (sentence correction) पूछी जाती है। साहित्य में काल-विभाजन (आदिकाल, भक्तिकाल, रीतिकाल, आधुनिक काल) और प्रमुख रचनाएँ याद रखना आवश्यक है। (In Hindi grammar, number, gender, tense, and case are important. Exams often ask error spotting or sentence correction. In literature, remember the periods and major works.)","body_hi":"हिंदी व्याकरण में वचन (singular/plural), लिंग (gender), काल (tense) और कारक (case) महत्वपूर्ण हैं। परीक्षा में अक्सर त्रुटि-निर्णय (error spotting) या वाक्य-शुद्धि (sentence correction) पूछी जाती है। साहित्य में काल-विभाजन (आदिकाल, भक्तिकाल, रीतिकाल, आधुनिक काल) और प्रमुख रचनाएँ याद रखना आवश्यक है। (In Hindi grammar, number, gender, tense, and case are important. Exams often ask error spotting or sentence correction. In literature, remember the periods and major works.)"}}],"questions":[{"q":"Which of the following is a 'तत्सम' (tatsam) word?","q_hi":"निम्नलिखित में से कौन-सा शब्द 'तत्सम' है?","o":["आँख","हाथ","अग्नि","कान"],"o_hi":["आँख","हाथ","अग्नि","कान"],"a":2,"exp":"तत्सम शब्द संस्कृत से ज्यों-के-त्यों लिए गए हैं। 'अग्नि' संस्कृत का शब्द है, जबकि आँख, हाथ, कान तद्भव हैं (संस्कृत के अक्षि, हस्त, कर्ण से बने)।","exp_hi":"तत्सम शब्द संस्कृत से ज्यों-के-त्यों लिए गए हैं। 'अग्नि' संस्कृत का शब्द है, जबकि आँख, हाथ, कान तद्भव हैं (संस्कृत के अक्षि, हस्त, कर्ण से बने)।","why":["आँख तद्भव है, क्योंकि यह संस्कृत के 'अक्षि' से बदलकर बना है।","हाथ भी तद्भव है, जो 'हस्त' से बना है।","कान भी तद्भव है, जो 'कर्ण' से बना है।"],"topic":"शब्द-भेद","level":2,"mode":"standard"},{"q":"In the sentence 'वह पुस्तक पढ़ता है', which word is the pronoun?","q_hi":"'वह पुस्तक पढ़ता है' वाक्य में सर्वनाम कौन-सा शब्द है?","o":["पुस्तक","पढ़ता","वह","है"],"o_hi":["पुस्तक","पढ़ता","वह","है"],"a":2,"exp":"'वह' एक सर्वनाम है जो किसी व्यक्ति या वस्तु के लिए प्रयुक्त होता है। यहाँ यह कर्ता के स्थान पर है।","exp_hi":"'वह' एक सर्वनाम है जो किसी व्यक्ति या वस्तु के लिए प्रयुक्त होता है। यहाँ यह कर्ता के स्थान पर है।","why":["'पुस्तक' एक संज्ञा है, क्योंकि यह किसी वस्तु का नाम है।","'पढ़ता' एक क्रिया है, क्योंकि यह काम को दर्शाता है।","'है' सहायक क्रिया है, सर्वनाम नहीं।"],"topic":"सर्वनाम","level":1,"mode":"standard"},{"q":"Who is known as the author of 'गोदान'?","q_hi":"'गोदान' के लेखक कौन हैं?","o":["सूर्यकांत त्रिपाठी 'निराला'","मुंशी प्रेमचंद","जयशंकर प्रसाद","मैथिलीशरण गुप्त"],"o_hi":["सूर्यकांत त्रिपाठी 'निराला'","मुंशी प्रेमचंद","जयशंकर प्रसाद","मैथिलीशरण गुप्त"],"a":1,"exp":"'गोदान' मुंशी प्रेमचंद का प्रसिद्ध उपन्यास है, जो ग्रामीण भारत की कहानी है।","exp_hi":"'गोदान' मुंशी प्रेमचंद का प्रसिद्ध उपन्यास है, जो ग्रामीण भारत की कहानी है।","why":["निराला छायावादी कवि थे, उन्होंने 'राम की शक्ति पूजा' जैसी रचनाएँ लिखीं।","जयशंकर प्रसाद ने 'कामायनी' लिखी।","मैथिलीशरण गुप्त ने 'भारत-भारती' लिखी।"],"topic":"साहित्य","level":1,"mode":"standard"},{"q":"Choose the correct synonym of 'अतिथि'.","q_hi":"'अतिथि' का सही पर्यायवाची चुनिए।","o":["शत्रु","मेहमान","मित्र","पड़ोसी"],"o_hi":["शत्रु","मेहमान","मित्र","पड़ोसी"],"a":1,"exp":"'अतिथि' का अर्थ है 'मेहमान'। यह संस्कृत से आया है जिसका अर्थ है 'जिसका कोई निश्चित समय न हो'।","exp_hi":"'अतिथि' का अर्थ है 'मेहमान'। यह संस्कृत से आया है जिसका अर्थ है 'जिसका कोई निश्चित समय न हो'।","why":["'शत्रु' का अर्थ है दुश्मन, जो विपरीत है।","'मित्र' का अर्थ है दोस्त, जो अतिथि नहीं है।","'पड़ोसी' का अर्थ है पास में रहने वाला, जो मेहमान नहीं है।"],"topic":"पर्यायवाची","level":1,"mode":"standard"},{"q":"Which of the following sentences has an error in gender agreement?","q_hi":"निम्नलिखित में से किस वाक्य में लिंग-संबंधी अशुद्धि है?","o":["लड़का स्कूल जाता है।","लड़की स्कूल जाती है।","बच्चे खेलते हैं।","माँ खाना बनाता है।"],"o_hi":["लड़का स्कूल जाता है।","लड़की स्कूल जाती है।","बच्चे खेलते हैं।","माँ खाना बनाता है।"],"a":3,"exp":"'माँ' स्त्रीलिंग है, इसलिए क्रिया 'बनाती है' होनी चाहिए, न कि 'बनाता है'। यह लिंग-संबंधी अशुद्धि है।","exp_hi":"'माँ' स्त्रीलिंग है, इसलिए क्रिया 'बनाती है' होनी चाहिए, न कि 'बनाता है'। यह लिंग-संबंधी अशुद्धि है।","why":["'लड़का स्कूल जाता है' सही है क्योंकि लड़का पुल्लिंग है और क्रिया 'जाता है' पुल्लिंग है।","'लड़की स्कूल जाती है' सही है क्योंकि लड़की स्त्रीलिंग है और क्रिया 'जाती है' स्त्रीलिंग है।","'बच्चे खेलते हैं' सही है क्योंकि बच्चे बहुवचन पुल्लिंग है और क्रिया 'खेलते हैं' सही है।"],"topic":"लिंग","level":2,"mode":"standard"}]},{"id":"gen-lang-hi-hindi-sectional-test-mtjzxvin","subject":"lang-hi","day":50,"level":1,"title":"Hindi Language and Literature","hi":"हिन्दी भाषा और साहित्य","concepts":[{"title":"Introduction to Hindi Literature and Grammar","title_hi":"हिन्दी साहित्य और व्याकरण का परिचय","simple":"Hindi is our national language and has a rich history of poets and grammar rules.","simple_hi":"हिन्दी हमारी राष्ट्रभाषा है और इसमें कवियों और व्याकरण के नियमों का समृद्ध इतिहास है।","intro":"","points":["हिन्दी का जन्म संस्कृत से हुआ है और यह देवनागरी लिपि में लिखी जाती है। (Hindi originated from Sanskrit and is written in Devanagari script.)","हिन्दी साहित्य का काल विभाजन: आदिकाल, भक्तिकाल, रीतिकाल और आधुनिक काल। (Hindi literature is divided into Adikal, Bhaktikal, Ritikal, and Adhunik Kal.)","प्रमुख कवि: तुलसीदास, सूरदास, कबीरदास, मीराबाई, प्रेमचंद, महादेवी वर्मा। (Prominent poets: Tulsidas, Surdas, Kabir, Mirabai, Premchand, Mahadevi Verma.)","व्याकरण के अंग: संधि, समास, कारक, सर्वनाम, विशेषण, क्रिया आदि। (Grammar components: Sandhi, Samas, Karak, Sarvanam, Visheshan, Kriya, etc.)","राष्ट्रकवि: मैथिलीशरण गुप्त, और भारतेंदु हरिश्चंद्र को हिन्दी का पितामह कहा जाता है। (National poet: Maithilisharan Gupt; Bharatendu Harishchandra is called the father of Hindi.)"],"example":"जैसे 'राम' शब्द में 'राम' कर्ता है, 'सीता' कर्म है, और 'गया' क्रिया है। वाक्य: 'राम सीता के साथ गया।' यहाँ 'के साथ' संबंध कारक का चिह्न है। (For example, in 'Ram went with Sita', Ram is the subject, Sita is the object, and 'went' is the verb. 'With' indicates the associative case.)","trick":"याद रखें: 'कबीर सूर तुलसी मीरा, चार कवि भक्तिकाल के पीरा' — यह चारों भक्तिकालीन कवि हैं। (Remember: 'Kabir, Sur, Tulsidas, Mira – four poets of Bhakti era' – this helps recall the main Bhakti poets.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"हिन्दी साहित्य में भक्तिकाल को दो धाराओं में बाँटा गया है: निर्गुण (कबीर, रैदास) और सगुण (सूर, तुलसी)। आधुनिक काल में खड़ी बोली का विकास हुआ और प्रेमचंद ने कहानी और उपन्यास को जनप्रिय बनाया। परीक्षा में अक्सर कवि की रचना, काल, और व्याकरण के नियमों पर प्रश्न पूछे जाते हैं। (In Hindi literature, Bhakti Kal is divided into Nirgun (Kabir, Raidas) and Sagun (Sur, Tulsidas). In the modern era, Khadi Boli developed, and Premchand popularized the story and novel. Exams often ask about poets' works, periods, and grammar rules.)","body_hi":"हिन्दी साहित्य में भक्तिकाल को दो धाराओं में बाँटा गया है: निर्गुण (कबीर, रैदास) और सगुण (सूर, तुलसी)। आधुनिक काल में खड़ी बोली का विकास हुआ और प्रेमचंद ने कहानी और उपन्यास को जनप्रिय बनाया। परीक्षा में अक्सर कवि की रचना, काल, और व्याकरण के नियमों पर प्रश्न पूछे जाते हैं। (In Hindi literature, Bhakti Kal is divided into Nirgun (Kabir, Raidas) and Sagun (Sur, Tulsidas). In the modern era, Khadi Boli developed, and Premchand popularized the story and novel. Exams often ask about poets' works, periods, and grammar rules.)"}}],"questions":[{"q":"Who is known as the 'father of Hindi'?","q_hi":"हिन्दी का पितामह किसे कहा जाता है?","o":["Bharatendu Harishchandra","Premchand","Maithilisharan Gupt","Tulsidas"],"o_hi":["भारतेंदु हरिश्चंद्र","प्रेमचंद","मैथिलीशरण गुप्त","तुलसीदास"],"a":0,"exp":"Bharatendu Harishchandra is called the father of Hindi because he modernized Hindi literature and wrote plays and essays.","exp_hi":"भारतेंदु हरिश्चंद्र को हिन्दी का पितामह कहा जाता है क्योंकि उन्होंने हिन्दी साहित्य को आधुनिक रूप दिया और नाटक व निबंध लिखे।","why":["प्रेमचंद को उपन्यास सम्राट कहा जाता है, पितामह नहीं। (Premchand is called the emperor of novels, not the father.)","मैथिलीशरण गुप्त राष्ट्रकवि हैं, पितामह नहीं। (Maithilisharan Gupt is the national poet, not the father.)","तुलसीदास भक्तिकालीन कवि हैं, आधुनिक नहीं। (Tulsidas is a Bhakti-era poet, not modern.)"],"topic":"Hindi Literature","level":1,"mode":"standard"},{"q":"Which of the following is a 'Sagun' (with attributes) poet of the Bhakti era?","q_hi":"निम्नलिखित में से कौन भक्तिकाल का सगुण कवि है?","o":["Kabir","Surdas","Raidas","Guru Nanak"],"o_hi":["कबीर","सूरदास","रैदास","गुरु नानक"],"a":1,"exp":"Surdas is a Sagun poet because he worshipped Lord Krishna in his poems, focusing on the divine with form.","exp_hi":"सूरदास सगुण कवि हैं क्योंकि उन्होंने अपनी रचनाओं में भगवान कृष्ण की भक्ति की, साकार रूप की उपासना की।","why":["कबीर निर्गुण कवि हैं, वे निराकार की उपासना करते थे। (Kabir is a Nirgun poet, he worshipped the formless.)","रैदास भी निर्गुण कवि हैं। (Raidas is also a Nirgun poet.)","गुरु नानक निर्गुण भक्ति के समर्थक थे। (Guru Nanak supported Nirgun bhakti.)"],"topic":"Bhakti Kal","level":1,"mode":"standard"},{"q":"In the sentence 'राम ने रावण को मारा', which word is the 'karma' (object)?","q_hi":"'राम ने रावण को मारा' वाक्य में कर्म (object) कौन-सा शब्द है?","o":["राम","रावण","मारा","ने"],"o_hi":["राम","रावण","मारा","ने"],"a":1,"exp":"The object is the one on whom the action is done. Ram does the action of killing, and Ravana is the one who is killed, so Ravana is the object.","exp_hi":"कर्म वह होता है जिस पर क्रिया का प्रभाव पड़ता है। राम ने मारने की क्रिया की और रावण मारा गया, इसलिए रावण कर्म है।","why":["'राम' कर्ता है, कर्म नहीं। (Ram is the subject, not the object.)","'मारा' क्रिया है, कर्म नहीं। (Mara is the verb, not the object.)","'ने' कारक चिह्न है, कर्म नहीं। (Ne is a case marker, not the object.)"],"topic":"Grammar","level":1,"mode":"standard"},{"q":"Who is the author of the epic poem 'Kamayani'?","q_hi":"महाकाव्य 'कामायनी' के रचयिता कौन हैं?","o":["Jaishankar Prasad","Suryakant Tripathi 'Nirala'","Sumitranandan Pant","Mahadevi Verma"],"o_hi":["जयशंकर प्रसाद","सूर्यकांत त्रिपाठी 'निराला'","सुमित्रानंदन पंत","महादेवी वर्मा"],"a":0,"exp":"Kamayani is a famous Hindi epic poem written by Jaishankar Prasad, a leading poet of the Chhayavad movement.","exp_hi":"कामायनी जयशंकर प्रसाद द्वारा रचित प्रसिद्ध हिन्दी महाकाव्य है, जो छायावादी युग के प्रमुख कवि थे।","why":["निराला ने 'राम की शक्ति पूजा' जैसी रचनाएँ लिखीं, कामायनी नहीं। (Nirala wrote works like 'Ram Ki Shakti Pooja', not Kamayani.)","पंत ने 'पल्लव' और 'ग्रंथि' लिखे। (Pant wrote 'Pallav' and 'Granthi'.)","महादेवी वर्मा छायावादी कवयित्री हैं, लेकिन उन्होंने कामायनी नहीं लिखी। (Mahadevi Verma is a Chhayavadi poetess, but she did not write Kamayani.)"],"topic":"Modern Hindi Literature","level":2,"mode":"standard"},{"q":"Which of the following is correctly matched?","q_hi":"निम्नलिखित में से कौन-सा युग्म सही है?","o":["Tulsidas – Ramcharitmanas","Kabir – Ramcharitmanas","Surdas – Ramcharitmanas","Premchand – Ramcharitmanas"],"o_hi":["तुलसीदास – रामचरितमानस","कबीर – रामचरितमानस","सूरदास – रामचरितमानस","प्रेमचंद – रामचरितमानस"],"a":0,"exp":"Tulsidas wrote the Ramcharitmanas, an epic poem in Awadhi based on the Ramayana.","exp_hi":"तुलसीदास ने रामचरितमानस की रचना की, जो रामायण पर आधारित अवधी में लिखा महाकाव्य है।","why":["कबीर ने दोहे और साखी लिखे, रामचरितमानस नहीं। (Kabir wrote dohas and sakhi, not Ramcharitmanas.)","सूरदास ने सूरसागर लिखा, रामचरितमानस नहीं। (Surdas wrote Sur Sagar, not Ramcharitmanas.)","प्रेमचंद ने उपन्यास और कहानियाँ लिखीं, रामचरितमानस नहीं। (Premchand wrote novels and stories, not Ramcharitmanas.)"],"topic":"Hindi Literature","level":1,"mode":"standard"}]}]/*__DATA_END__*/);
